def create_baseline_policies(apps, schema_editor):
    policy = apps.get_model("leave_elm", "LeavePolicy")
    rows = (
        ("CL", "8", "8", True, True, False, False, False, False),
        ("RH", "2", "2", True, True, False, False, False, False),
        ("SCL", "15", "15", True, True, False, False, False, False),
        ("EL", "0", "30", True, True, True, False, False, True),
        ("COL", "20", "20", True, True, True, False, False, True),
        ("VL", "60", "0", True, False, True, True, False, False),
    )
    for (category, faculty, staff, faculty_eligible, staff_eligible, continuous,
         vacation, evidence, carry) in rows:
        policy.objects.update_or_create(
            category=category,
            defaults={
                "faculty_entitlement": faculty,
                "staff_entitlement": staff,
                "faculty_eligible": faculty_eligible,
                "staff_eligible": staff_eligible,
                "continuous_days": continuous,
                "vacation_period_required": vacation,
                "evidence_required": evidence,
                "carry_forward": carry,
            },
        )


def remove_baseline_policies(apps, schema_editor):
    apps.get_model("leave_elm", "LeavePolicy").objects.all().delete()


